import {civicRoots} from './civic-footprints.js?v=sawtooth-factory-1';
export const policeOwners=c=>[-1,...civicRoots(c).filter(t=>t.type==='police').map(t=>t.y*c.size+t.x)];
export function prunePoliceOrders(c){const owners=new Set(policeOwners(c));c.emergency.policeUnits=c.emergency.policeUnits.filter(p=>owners.has(p.owner));}
export function recallPolice(c,owner){const e=c.emergency;if(!e.active)return{ok:false,error:'There is no active emergency.'};if(!e.policeUnits.some(p=>p.owner===owner))return{ok:false,error:'That squad has no dispatch order.'};e.policeUnits=e.policeUnits.filter(p=>p.owner!==owner);return{ok:true};}
export function assignPolice(c,x,y){prunePoliceOrders(c);const e=c.emergency,owners=policeOwners(c),assigned=new Set(e.policeUnits.map(p=>p.owner));let owner=owners.find(id=>!assigned.has(id));if(owner===undefined){owner=owners[e.nextPolice%owners.length];e.nextPolice=(e.nextPolice+1)%owners.length;}const at=e.policeUnits.findIndex(p=>p.owner===owner),order={x,y,owner};if(at<0)e.policeUnits.push(order);else e.policeUnits[at]=order;}
export function policeOrdersReport(c){const e=c.emergency;if(!e.active)return'';return `<h3>Dispatched police squads</h3>${e.policeUnits.length?'<ul>'+e.policeUnits.map(p=>`<li>${p.owner===-1?'Volunteer brigade':'Station at '+(p.owner%c.size+1)+', '+(Math.floor(p.owner/c.size)+1)} → Tile ${p.x+1}, ${p.y+1} <button data-police-recall="${p.owner}">Recall squad</button></li>`).join('')+'</ul>':'<p>No manual police orders.</p>'}<p>Recall a station squad to make it available for automatic response in its precinct. Recalling volunteers removes their current assignment. Dispatch again to send the next available squad.</p>`;}
